#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define NV 50257
#define NC 256
#define ND 768
#define NL 12
#define NH 12
#define HD 64
static float*W;static long N;
void ln(float*o,float*x,float*g,float*b,int ga){
 float m=0,v=0;for(int i=0;i<ND;i++)m+=x[i];m/=ND;
 for(int i=0;i<ND;i++){float d=x[i]-m;v+=d*d;}v/=ND;
 float s=1.0f/sqrtf(v+1e-5f);
 for(int i=0;i<ND;i++)o[i]=(x[i]-m)*s*(g[i]+ga)+b[i];
}
float ge(float x){return 0.5f*x*(1.0f+erff(x*0.70710678118654752f));}
long catb=0,catw=2304,cpjb=1771776,cpjw=1772544,ln1b=2362368,ln1g=2363136,ln2b=2363904,ln2g=2364672,cfcb=2365440,cfcw=2368512,cpcb=4727808,cpcw=4728576;
void fwd(int*T,int Tn,int ga,int numeric,float*lgs){
 long wte=N-38597376,wpe=N-38597376-786432,lfg=N-38597376-786432-768,lfb=N-38597376-786432-1536;
 static float x[NC][ND],h[NC][ND],q[NC][ND],k[NC][ND],v[NC][ND],at[NC][ND],qk[2304],h1[3072],tm[ND];
 for(int t=0;t<Tn;t++)for(int i=0;i<ND;i++)x[t][i]=W[wte+T[t]*ND+i]+W[wpe+t*ND+i];
 long nblk[12];long bl[12]={0,7087872,14175744,21263616,28351488,35439360,42527232,49615104,56702976,63790848,70878720,77966592};
 int bn[12]={0,1,10,11,2,3,4,5,6,7,8,9};
 for(int i=0;i<12;i++)nblk[i]=numeric?bl[i]:bl[0]; // placeholder
 if(!numeric)for(int i=0;i<12;i++)nblk[bn[i]]=bl[i];
 for(int l=0;l<NL;l++){
  long b=nblk[l];
  for(int t=0;t<Tn;t++)ln(h[t],x[t],W+b+ln1g,W+b+ln1b,ga);
  for(int t=0;t<Tn;t++){
   for(int j=0;j<2304;j++){float s=W[b+catb+j];for(int i=0;i<ND;i++)s+=h[t][i]*W[b+catw+i*2304+j];qk[j]=s;}
   memcpy(q[t],qk,ND*4);memcpy(k[t],qk+ND,ND*4);memcpy(v[t],qk+2*ND,ND*4);
  }
  for(int hi=0;hi<NH;hi++)for(int t=0;t<Tn;t++){
   float sc[NC];
   for(int t2=0;t2<=t;t2++){float s=0;for(int d=0;d<HD;d++)s+=q[t][hi*HD+d]*k[t2][hi*HD+d];sc[t2]=s*0.125f;}
   float mx=sc[0];for(int t2=1;t2<=t;t2++)if(sc[t2]>mx)mx=sc[t2];
   float sm=0;for(int t2=0;t2<=t;t2++){sc[t2]=expf(sc[t2]-mx);sm+=sc[t2];}
   for(int t2=0;t2<=t;t2++)sc[t2]/=sm;
   for(int d=0;d<HD;d++){float s=0;for(int t2=0;t2<=t;t2++)s+=sc[t2]*v[t2][hi*HD+d];at[t][hi*HD+d]=s;}
  }
  for(int t=0;t<Tn;t++){
   for(int j=0;j<ND;j++){float s=W[b+cpjb+j];for(int i=0;i<ND;i++)s+=at[t][i]*W[b+cpjw+i*ND+j];tm[j]=s;}
   for(int i=0;i<ND;i++)x[t][i]+=tm[i];
  }
  for(int t=0;t<Tn;t++){
   ln(h[t],x[t],W+b+ln2g,W+b+ln2b,ga);
   for(int j=0;j<3072;j++){float s=W[b+cfcb+j];for(int i=0;i<ND;i++)s+=h[t][i]*W[b+cfcw+i*3072+j];h1[j]=ge(s);}
   for(int j=0;j<ND;j++){float s=W[b+cpcb+j];for(int i=0;i<3072;i++)s+=h1[i]*W[b+cpcw+i*ND+j];tm[j]=s;}
   for(int i=0;i<ND;i++)x[t][i]+=tm[i];
  }
 }
 ln(tm,x[Tn-1],W+lfg,W+lfb,ga);
 for(int i=0;i<NV;i++){float s=0;for(int j=0;j<ND;j++)s+=tm[j]*W[wte+i*ND+j];lgs[i]=s;}
}
int main(){
 FILE*f=fopen("gpt2-124M.ckpt","rb");fseek(f,0,SEEK_END);N=ftell(f)/4;fseek(f,0,SEEK_SET);
 W=malloc(N*4);if(fread(W,4,N,f)!=N)return 1;fclose(f);
 static float lgs[NV];
 const char*cn[]={"str+ga0","str+ga1","num+ga0","num+ga1"};
 int configs[4][2]={{0,0},{0,1},{1,0},{1,1}};
 for(int c=0;c<4;c++){
  static int toks[NC]={464,2361,6381};int T=3;
  printf("\n%s:",cn[c]);
  for(int i=0;i<20;i++){fwd(toks,T,configs[c][1],configs[c][0],lgs);int b=0;for(int j=1;j<NV;j++)if(lgs[j]>lgs[b])b=j;printf(" %d",b);toks[T++]=b;}
  printf("\n");
 }
 return 0;
}
